2225  otError MleRouter::HandleChildUpdateRequest(const Message &         aMessage,
  2226                                              const Ip6::MessageInfo &aMessageInfo,
  2227                                              uint32_t                aKeySequence)
  2228  {
  2229      static const uint8_t kMaxResponseTlvs = 10;
  2230
  2231      otError         error = OT_ERROR_NONE;
  2232      Mac::ExtAddress macAddr;
  2233      ModeTlv         mode;
  2234      ChallengeTlv    challenge;
  2235      LeaderDataTlv   leaderData;
  2236      TimeoutTlv      timeout;
  2237      Child *         child;
  2238      TlvRequestTlv   tlvRequest;
  2239      uint8_t         tlvs[kMaxResponseTlvs];
  2240      uint8_t         tlvslength                = 0;
  2241      uint16_t        addressRegistrationOffset = 0;
  2242      bool            childDidChange            = false;
  2243
  2244      LogMleMessage("Receive Child Update Request from child", aMessageInfo.GetPeerAddr());
  2245
  2246      // Mode
  2247      SuccessOrExit(error = Tlv::GetTlv(aMessage, Tlv::kMode, sizeof(mode), mode));
  2248      VerifyOrExit(mode.IsValid(), error = OT_ERROR_PARSE);
  2249
  2250      // Find Child
  2251      aMessageInfo.GetPeerAddr().ToExtAddress(macAddr);
  2252      child = GetChildTable().FindChild(macAddr, ChildTable::kInStateAnyExceptInvalid);
  2253
  2254      tlvs[tlvslength++] = Tlv::kSourceAddress;
  2255
  2256      // Not proceed if the Child Update Request is from the peer which is not the device's child or
  2257      // which was the device's child but becomes invalid.
  2258      if (child == NULL || child->GetState() == Neighbor::kStateInvalid)
  2259      {
  2260          // For invalid non-sleepy child, Send Child Update Response with status TLV (error)
  2261          if (mode.GetMode() & ModeTlv::kModeRxOnWhenIdle)
  2262          {
  2263              tlvs[tlvslength++] = Tlv::kStatus;
  2264              SendChildUpdateResponse(NULL, aMessageInfo, tlvs, tlvslength, NULL);
  2265          }
  2266
  2267          ExitNow();
  2268      }
  2269
  2270      if (child->GetDeviceMode() != mode.GetMode())
  2271      {
  2272          otLogNoteMle("Child 0x%04x mode change 0x%02x -> 0x%02x [rx-on:%s, sec-data-req:%s, ftd:%s, full-netdata:%s]",
  2273                       child->GetRloc16(), child->GetDeviceMode(), mode.GetMode(),
  2274                       (mode.GetMode() & ModeTlv::kModeRxOnWhenIdle) ? "yes" : " no",
  2275                       (mode.GetMode() & ModeTlv::kModeSecureDataRequest) ? "yes" : " no",
  2276                       (mode.GetMode() & ModeTlv::kModeFullThreadDevice) ? "yes" : "no",
  2277                       (mode.GetMode() & ModeTlv::kModeFullNetworkData) ? "yes" : "no");
  2278
  2279          child->SetDeviceMode(mode.GetMode());
  2280          childDidChange = true;
  2281
  2282          if (!(mode.GetMode() & ModeTlv::kModeRxOnWhenIdle) && (child->GetState() == Neighbor::kStateValid))
  2283          {
  2284              GetNetif().GetMeshForwarder().GetSourceMatchController().SetSrcMatchAsShort(*child, true);
  2285          }
  2286      }
  2287
  2288      tlvs[tlvslength++] = Tlv::kMode;
  2289
  2290      // Parent MUST include Leader Data TLV in Child Update Response
  2291      tlvs[tlvslength++] = Tlv::kLeaderData;
  2292
  2293      // Challenge
  2294      if (Tlv::GetTlv(aMessage, Tlv::kChallenge, sizeof(challenge), challenge) == OT_ERROR_NONE)
  2295      {
  2296          VerifyOrExit(challenge.IsValid(), error = OT_ERROR_PARSE);
  2297          tlvs[tlvslength++] = Tlv::kResponse;
  2298          tlvs[tlvslength++] = Tlv::kMleFrameCounter;
  2299          tlvs[tlvslength++] = Tlv::kLinkFrameCounter;
  2300      }
  2301
  2302      // Ip6 Address TLV
  2303      if (Tlv::GetOffset(aMessage, Tlv::kAddressRegistration, addressRegistrationOffset) == OT_ERROR_NONE)
  2304      {
  2305          SuccessOrExit(error = UpdateChildAddresses(aMessage, addressRegistrationOffset, *child));
  2306          tlvs[tlvslength++] = Tlv::kAddressRegistration;
  2307      }
  2308
  2309      // Leader Data
  2310      if (Tlv::GetTlv(aMessage, Tlv::kLeaderData, sizeof(leaderData), leaderData) == OT_ERROR_NONE)
  2311      {
  2312          VerifyOrExit(leaderData.IsValid(), error = OT_ERROR_PARSE);
  2313      }
  2314
  2315      // Timeout
  2316      if (Tlv::GetTlv(aMessage, Tlv::kTimeout, sizeof(timeout), timeout) == OT_ERROR_NONE)
  2317      {
  2318          VerifyOrExit(timeout.IsValid(), error = OT_ERROR_PARSE);
  2319
  2320          if (child->GetTimeout() != timeout.GetTimeout())
  2321          {
  2322              child->SetTimeout(timeout.GetTimeout());
  2323              childDidChange = true;
  2324          }
  2325
  2326          tlvs[tlvslength++] = Tlv::kTimeout;
  2327      }
  2328
  2329      // TLV Request
  2330      if (Tlv::GetTlv(aMessage, Tlv::kTlvRequest, sizeof(tlvRequest), tlvRequest) == OT_ERROR_NONE)
  2331      {
  2332          uint8_t            tlv;
  2333          TlvRequestIterator iterator = TLVREQUESTTLV_ITERATOR_INIT;
  2334
  2335          VerifyOrExit(tlvRequest.IsValid() && tlvRequest.GetLength() <= (kMaxResponseTlvs - tlvslength),
  2336                       error = OT_ERROR_PARSE);
  2337
  2338          while (tlvRequest.GetNextTlv(iterator, tlv) == OT_ERROR_NONE)
  2339          {
  2340              // Here skips Tlv::kLeaderData because it has already been included by default
  2341              if (tlv != Tlv::kLeaderData)
  2342              {
  2343                  tlvs[tlvslength++] = tlv;
  2344              }
  2345          }
  2346      }
  2347
  2348      child->SetLastHeard(TimerMilli::GetNow());
  2349
  2350      if (child->IsStateRestoring())
  2351      {
  2352          SetChildStateToValid(*child);
  2353          child->SetKeySequence(aKeySequence);
  2354      }
  2355      else if (child->GetState() == Neighbor::kStateValid)
  2356      {
  2357          if (childDidChange)
  2358          {
  2359              StoreChild(*child);
  2360          }
  2361      }
  2362
  2363      SendChildUpdateResponse(child, aMessageInfo, tlvs, tlvslength, &challenge);
  2364
  2365  exit:
  2366      return error;
  2367  }
