  2483  otError MleRouter::HandleDataRequest(const Message &aMessage, const Ip6::MessageInfo &aMessageInfo)
  2484  {
  2485      ThreadNetif &       netif = GetNetif();
  2486      otError             error = OT_ERROR_NONE;
  2487      TlvRequestTlv       tlvRequest;
  2488      ActiveTimestampTlv  activeTimestamp;
  2489      PendingTimestampTlv pendingTimestamp;
  2490      uint8_t             tlvs[4];
  2491      uint8_t             numTlvs;
  2492
  2493      LogMleMessage("Receive Data Request", aMessageInfo.GetPeerAddr());
  2494
  2495      // TLV Request
  2496      SuccessOrExit(error = Tlv::GetTlv(aMessage, Tlv::kTlvRequest, sizeof(tlvRequest), tlvRequest));
  2497      VerifyOrExit(tlvRequest.IsValid() && tlvRequest.GetLength() <= sizeof(tlvs), error = OT_ERROR_PARSE);
  2498
  2499      // Active Timestamp
  2500      activeTimestamp.SetLength(0);
  2501
  2502      if (Tlv::GetTlv(aMessage, Tlv::kActiveTimestamp, sizeof(activeTimestamp), activeTimestamp) == OT_ERROR_NONE)
  2503      {
  2504          VerifyOrExit(activeTimestamp.IsValid(), error = OT_ERROR_PARSE);
  2505      }
